      let child=value,depth=0;const seen=new Set([child]);
      while(true){const parent=seriesCopyrightParents.get(child)||[...copyrightGroups].find(([,children])=>children.includes(child))?.[0];if(!parent||seen.has(parent))break;seen.add(parent);depth++;child=parent;}
