      const row=document.createElement('label'),box=document.createElement('input');
      if(catalogView==='character'&&key==='copyright'&&(value==='Pokemon Creatures'||voiceCopyrights.has(value)||originalCategoryLabels.has(value)||chineseCopyrights.has(value)||kyotoCopyrights.has(value)))row.className='facet-child';
      box.type='checkbox';box.checked=filters[key].has(value);box.setAttribute('aria-label',value);box.title=t('facetOptionHelp',{value:facetValueLabel(key,value)});row.title=box.title;
      box.onchange=()=>{if(box.checked)filters[key].add(value);else filters[key].delete(value);page=1;selected.clear();storePreferences();render();};
      const text=document.createElement('span');text.textContent=facetValueLabel(key,value);const number=document.createElement('small');number.textContent=count;
