    if(!facetObserver)facetObserver=new ResizeObserver(entries=>{let changed=false;entries.forEach(entry=>{const key=entry.target.dataset.facet,height=Math.round(entry.contentRect.height);if(height>65&&heights[key]!==height){heights[key]=height;changed=true;const state=facetSections.get(key);if(state?.list===entry.target)drawTrialFacetWindow(state);}});if(changed)storePreferences();});
